import { z } from "zod";
export const QACheck = z.object({
  id: z.string().regex(/^QA-\d$/),
  user_sees: z.string(),  // "With no projects, the table shows 'No projects yet'"
  reads: z.array(z.enum(["test_id", "aria_role", "visible_text", "row_count", "api_response"])).min(1),
  level: z.enum(["unit", "story", "e2e", "api", "browser_only"]),
  edge_case: z.boolean().default(false),
  proof: z.enum(["video", "screenshots_760_1440", "transcript", "test_output"]),
});
export const Step = z.object({
  what: z.string(),
  files: z.array(z.string()),
  model: z.enum(["claude-opus-5-5", "claude-sonnet-5-5", "claude-haiku-5-5"]).default("claude-opus-5-5"),
  effort: z.enum(["low", "medium", "high", "xhigh"]).default("medium"),
});
const ScreenState = z.enum(["loading", "empty", "error", "filled", "bad_data"]);

export const Plan = z.object({
  definition_of_done: z.array(z.string()).min(1).max(5),  // first, in the requester's words
  qa_plan: z.array(QACheck).min(3).max(5),
  screen_states: z.partialRecord(ScreenState, z.string()).optional(),  // UI only
  steps: z.array(Step),
  sandbox: z.enum(["lite", "full", "wide"]),  // plan small, build big
  workflow: z.string().optional(),  // why a dynamic workflow helps here, and roughly how big
  estimate_minutes: z.number().int(),  // Nova's own guess; measured, never a limit
  risk: z.enum(["low", "med", "high"]),
  risk_reason: z.string(),
}).superRefine((p, ctx) => {  // the harness sends these errors back to the planner to fix
  const ui = p.steps.some((s) => s.files.some((f) => f.startsWith("frontend/src/")));
  if (!p.qa_plan.some((c) => c.edge_case) || (ui && !p.screen_states))
    ctx.addIssue({ code: "custom", message: "the QA plan needs an edge case, and a UI change lists how to reach its screen states" });
});
export type Plan = z.infer<typeof Plan>;

import { Plan } from "@rhinohealth/ai-agents-shared";
import { z } from "zod";
// The planner session ends with structured output in the Plan shape (G4-07, how 1).
export const planOutputFormat = { type: "json_schema" as const, schema: z.toJSONSchema(Plan, { io: "input" }) };
// After the session: check the result once more, and send any error back to the planner to fix.
export function acceptPlan(structuredOutput: unknown): { plan: Plan } | { fix: string } {
  const parsed = Plan.safeParse(structuredOutput);
  if (parsed.success) return { plan: parsed.data };
  return { fix: parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("\n") };
}

import { proxyActivities } from "@temporalio/workflow";
import type * as activities from "../activities/index.js";
import type { Readiness } from "../activities/readiness.js";
import { waitForPerson } from "../waiting.js";  // G3: remind after 1 day, park after 2
import { LONG } from "../policies.js";  // G3-29: a 7-day safety net and 2-minute heartbeats, never a work limit

const { checkReadiness } = proxyActivities<typeof activities>({ startToCloseTimeout: "5 minutes" });
const { writeGrillQuestions } = proxyActivities<typeof activities>(LONG);  // an Opus session: never cut off
const { handBack, postQuestions, recordAnswers } = proxyActivities<typeof activities>({ startToCloseTimeout: "2 minutes" });

async function readinessAndGrill(h: Handoff, run: RunState): Promise<Readiness | undefined> {
  let r = await checkReadiness(h.key);
  if (r.verdict === "hand_back") {
    await handBack(h.key, h.requester, r.reason);
    return undefined;
  }

  let rounds = 0;
  while (r.verdict === "ask" || (r.size !== "small" && rounds === 0)) {
    const questions = r.questions.length ? r.questions : await writeGrillQuestions(h.key);  // Opus 5.5 medium, no VM
    if (!questions.length) break;
    await setState(run, "Needs info", `${questions.length} questions for the requester`);
    run.answer = undefined;  // before posting, so a quick answer is not lost; the answerQuestion signal (G3) sets it
    await postQuestions(h.key, h.requester, questions);
    if (!(await waitForPerson(run, "question", () => run.answer !== undefined, h))) return undefined;  // parked or stopped
    await recordAnswers(h.key, questions, run.answer!);
    r = await checkReadiness(h.key);
    rounds += 1;
    if (rounds === 2 && r.verdict === "ask") {
      await flagToRequester(run, "The same questions are still open. Please edit the ticket or reply.");
      break;
    }
  }
  return r;
}

